import Mathlib
import Aesop
set_option maxHeartbeats 2000000
set_option autoImplicit false
open BigOperators Real Nat Topology Rat

theorem bounded_geometric_term_law
  (a : ℕ → ℚ)
  (d : ℚ)
  (h₀ : ∀ n, a (n + 1) = a n * d)
  (h₁ : a 0 = 27 / 125)
  (h₂ : a 1 = 9 / 25)
   :
  d = 5 / 3 ∧ ∀ n : ℕ, n ≤ 5 → a n = (27 / 125) * (5 / 3) ^ n := by
  have h_d : d = 5 / 3 := by
    have h₃ : a 1 = a 0 * d := h₀ 0
    rw [h₁] at h₃
    rw [h₂] at h₃
    norm_num at h₃ ⊢
    <;>
    (try norm_num at h₃ ⊢) <;>
    (try linarith) <;>
    (try ring_nf at h₃ ⊢) <;>
    (try norm_num at h₃ ⊢) <;>
    (try linarith)
    <;>
    (try
      {
        nlinarith
      })
    <;>
    (try
      {
        field_simp at h₃ ⊢
        <;> ring_nf at h₃ ⊢ <;> norm_num at h₃ ⊢ <;> linarith
      })
    <;>
    (try
      {
        nlinarith
      })
    <;>
    (try
      {
        ring_nf at h₃ ⊢ <;> norm_num at h₃ ⊢ <;> linarith
      })
    <;>
    (try
      {
        nlinarith
      })

  have h_general : ∀ n : ℕ, a n = (27 / 125) * d ^ n := by
    intro n
    have h₃ : ∀ n : ℕ, a n = (27 / 125) * d ^ n := by
      intro n
      induction n with
      | zero =>
        norm_num [h₁] at *
        <;>
        simp_all [pow_zero]
        <;>
        ring_nf at *
        <;>
        norm_num at *
        <;>
        linarith
      | succ n ih =>
        have h₄ := h₀ n
        have h₅ := h₀ (n + 1)
        simp [ih, pow_succ, mul_assoc] at h₄ h₅ ⊢
        <;>
        ring_nf at h₄ h₅ ⊢ <;>
        norm_num at h₄ h₅ ⊢ <;>
        (try linarith) <;>
        (try nlinarith) <;>
        (try
          {
            simp_all [pow_succ, mul_assoc]
            <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            field_simp at * <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            simp_all [pow_succ, mul_assoc]
            <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            field_simp at * <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            simp_all [pow_succ, mul_assoc]
            <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            field_simp at * <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            simp_all [pow_succ, mul_assoc]
            <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            field_simp at * <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            simp_all [pow_succ, mul_assoc]
            <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            field_simp at * <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            simp_all [pow_succ, mul_assoc]
            <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            field_simp at * <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            simp_all [pow_succ, mul_assoc]
            <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            field_simp at * <;> ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
        <;>
        (try
          {
            ring_nf at * <;> norm_num at * <;> linarith
          })
        <;>
        (try
          {
            nlinarith
          })
        <;>
        (try
          {
            linarith
          })
    exact h₃ n

  have h_main : ∀ n : ℕ, n ≤ 5 → a n = (27 / 125) * (5 / 3) ^ n := by
    intro n hn
    have h₃ : a n = (27 / 125) * d ^ n := h_general n
    rw [h₃]
    have h₄ : d = 5 / 3 := h_d
    rw [h₄]
    <;>
    (try norm_num) <;>
    (try simp [pow_succ, mul_assoc]) <;>
    (try ring_nf) <;>
    (try norm_num) <;>
    (try
      {
        have h₅ : n ≤ 5 := hn
        interval_cases n <;> norm_num <;>
        (try ring_nf at *) <;>
        (try norm_num at *) <;>
        (try linarith)
      })
    <;>
    (try
      {
        have h₅ : n ≤ 5 := hn
        interval_cases n <;> norm_num <;>
        (try ring_nf at *) <;>
        (try norm_num at *) <;>
        (try linarith)
      })
    <;>
    (try
      {
        have h₅ : n ≤ 5 := hn
        interval_cases n <;> norm_num <;>
        (try ring_nf at *) <;>
        (try norm_num at *) <;>
        (try linarith)
      })

  have h_final : d = 5 / 3 ∧ ∀ n : ℕ, n ≤ 5 → a n = (27 / 125) * (5 / 3) ^ n := by
    refine' ⟨h_d, _⟩
    intro n hn
    have h₃ : a n = (27 / 125) * (5 / 3) ^ n := h_main n hn
    exact h₃

  exact h_final
